for p,(topic,prompt,opts,ans,ex) in zip(FILES,ITEMS):
 d=json.loads(p.read_text()); d['prompt']=prompt; d['options']=[{'id':chr(65+i),'text':t} for i,t in enumerate(opts)]; d['answer']={'value':ans,'explanation':ex}; d['solutionStrategy']=f'先辨認動能、重力位能或彈性位能的變化，再用K=1/2mv²、U=mgh與機械能守恆追蹤互換；本題聚焦於{topic}。'; d['solutionSteps']=['先圈出質量、速度、高度、彈簧或摩擦等條件。','判斷哪種能量增加、哪種減少；無摩擦時使用K+U守恆，有摩擦時納入熱能。',f'依公式或能量守恆逐項比對，得到答案{ans}。',f'回看解析：{ex}','最後確認參考面只影響位能零點，不會改變可觀測的能量差。']; d['reviewStatus']='draft'; d['updatedAt']='2026-09-08'; d['provenance']['authoringNote']='依官方課綱與公開會考、公立國中試題所呈現的力學能、動能、位能互換與守恆推理方向獨立改寫；未複製原題文字、選項、圖表或答案；待第二輪 AI／Terra 內容複核。'; p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
